@Test
public void testRollbackUsingXmlQueueToQueueRequestReplyUsingDynamicMessageSelector() throws Exception {
    final ConditionalExceptionProcessor cp = new ConditionalExceptionProcessor(5);
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            Policy required = context().getRegistry().lookupByNameAndType("PROPAGATION_REQUIRED_POLICY", SpringTransactionPolicy.class);
            from("activemq:queue:QueueToQueueRequestReplyTransactionIT").policy(required).process(cp).to("activemq-1:queue:QueueToQueueRequestReplyTransactionIT.bar?replyTo=queue:QueueToQueueRequestReplyTransactionIT.bar.reply");
            from("activemq-1:queue:QueueToQueueRequestReplyTransactionIT.bar").process(e -> {
                String request = e.getIn().getBody(String.class);
                Message out = e.getMessage();
                String selectorValue = e.getIn().getHeader("camelProvider", String.class);
                if (selectorValue != null) {
                    out.setHeader("camelProvider", selectorValue);
                }
                out.setBody("Re: " + request);
            });
        }
    });
    for (int i = 0; i < 5; ++i) {
        Object reply = template.requestBody("activemq:queue:QueueToQueueRequestReplyTransactionIT", "blah" + i);
        assertEquals("Re: blah" + i, reply, "Received unexpected reply at item " + i);
        assertNull(cp.getErrorMessage(), cp.getErrorMessage());
    }
}

