@Test
public void testPriority() throws Exception {
    int messages = 100;
    ExecutorService executor = Executors.newFixedThreadPool(5);
    for (int i = 0; i < messages; i++) {
        final int index = i;
        executor.submit(() -> {
            template.sendBody("jms:queue:JmsPriorityConsumerTest", "Message " + index);
            return null;
        });
    }
    executor.awaitTermination(5, TimeUnit.SECONDS);
    MockEndpoint lowPriority = getMockEndpoint("mock:lowPriority");
    MockEndpoint mediumPriority = getMockEndpoint("mock:mediumPriority");
    MockEndpoint highPriority = getMockEndpoint("mock:highPriority");
    Assertions.assertThat(highPriority.getReceivedExchanges().size()).isGreaterThan(mediumPriority.getReceivedExchanges().size());
    Assertions.assertThat(mediumPriority.getReceivedExchanges().size()).isGreaterThanOrEqualTo(lowPriority.getReceivedExchanges().size());
}

