        public void run() {
            consumer.receive();
            receiveFlag = true;
        }
    }).start();
    StopWatch watch = new StopWatch();
    while (!receiveFlag) {
        if ((watch.taken()) > BLOCKING_THRESHOLD) {
            /* Passed test. */
            return;
        }
        Thread.sleep(50L);
    }
    fail("Method receive() has returned from call.");
}

