@Test
public void testComponentConfigurationAndConfigurationPrecedence() {
    Main main = new Main();
    try {
        main.setOverrideProperties(getTestProperties());
        main.setDefaultPropertyPlaceholderLocation("false");
        main.configure().addRoutesBuilder(createRouteBuilder());
        main.start();
        assertThat(main.getCamelTemplate().requestBody("kamelet:setBody/test", "", String.class)).isEqualTo("from-component-route");
        assertThat(main.getCamelTemplate().requestBody("kamelet:setBody", "", String.class)).isEqualTo("from-component-template");
        // uri properties have precedence over component properties.
        assertThat(main.getCamelTemplate().requestBody("kamelet:setBody?bodyValue={{bodyValue}}", "", String.class)).isEqualTo("from-uri");
    } catch (Exception e) {
        fail(e);
    } finally {
        main.stop();
    }
}

