@Test
public void testIdleConnectionTimeout() throws Exception {
    complete.expectedMessageCount(2);
    writeEx.expectedMessageCount(0);
    receiveEx.expectedMessageCount(0);
    NotifyBuilder done = new NotifyBuilder(context).whenCompleted(2).create();
    // Need to send one message to get the connection established
    source.sendBody(Hl7TestMessageGenerator.generateMessage());
    source.sendBody(Hl7TestMessageGenerator.generateMessage());
    Awaitility.await().atMost(IDLE_TIMEOUT / 2, TimeUnit.MILLISECONDS).untilAsserted(() -> {
        assertTrue(done.matches(5, TimeUnit.SECONDS), "Should have completed two exchanges");
        MockEndpoint.assertIsSatisfied(context, 5, TimeUnit.SECONDS);
    });
    Awaitility.await().atMost((long) (IDLE_TIMEOUT * 1.1), TimeUnit.MILLISECONDS).untilAsserted(() -> {
        assertThrows(MllpJUnitResourceException.class, () -> mllpServer.checkClientConnections());
    });
}

@Test
public void testReconnectAfterIdleConnectionTimeout() throws Exception {
    complete.expectedMessageCount(3);
    writeEx.expectedMessageCount(0);
    receiveEx.expectedMessageCount(0);
    NotifyBuilder done = new NotifyBuilder(context).whenCompleted(2).create();
    // Need to send one message to get the connection established
    source.sendBody(Hl7TestMessageGenerator.generateMessage());
    source.sendBody(Hl7TestMessageGenerator.generateMessage());
    Awaitility.await().atMost(IDLE_TIMEOUT / 2, TimeUnit.MILLISECONDS).untilAsserted(() -> assertTrue(done.matches(5, TimeUnit.SECONDS), "Should have completed two exchanges"));
    Awaitility.await().untilAsserted(() -> {
        assertThrows(MllpJUnitResourceException.class, () -> mllpServer.checkClientConnections(), "Should receive and exception for the closed connection");
        source.sendBody(Hl7TestMessageGenerator.generateMessage());
        MockEndpoint.assertIsSatisfied(context, 5, TimeUnit.SECONDS);
    });
    log.debug("Breakpoint");
}

