@Test
public void testInduceParseAndThenOkException() {
    pumpDataIntoTestCollection();
    // notice missing quote at the end of Einstein
    Exception ex = assertThrows(CamelExecutionException.class, () -> template.requestBody("direct:findOneByQuery", "{\"scientist\": \"Einstein}"), "Should have thrown an exception");
