@Test
public void testSSLInOutWithNettyConsumer() throws Exception {
    Main main = new Main();
    main.configure().sslConfig().setEnabled(true);
    main.configure().sslConfig().setKeyStore(this.getClass().getClassLoader().getResource("keystore.jks").toString());
    main.configure().sslConfig().setKeystorePassword("changeit");
    main.configure().sslConfig().setTrustStore(this.getClass().getClassLoader().getResource("keystore.jks").toString());
    main.configure().sslConfig().setTrustStorePassword("changeit");
    main.addProperty("camel.component.netty.useglobalsslcontextparameters", "true");
    main.configure().addRoutesBuilder(new RouteBuilder() {

        public void configure() {
            // needClientAuth=true so we can get the client certificate details
            from("netty:tcp://localhost:" + getPort() + "?sync=true&ssl=true&needClientAuth=true").process(exchange -> {
                SSLSession session = exchange.getIn().getHeader(NettyConstants.NETTY_SSL_SESSION, SSLSession.class);
                if (session != null) {
                    X509Certificate cert = (X509Certificate) session.getPeerCertificates()[0];
                    Principal principal = cert.getSubjectDN();
                    log.info("Client Cert SubjectDN: {}", principal.getName());
                    exchange.getMessage().setBody("When You Go Home, Tell Them Of Us And Say, For Your Tomorrow, We Gave Our Today.");
                } else {
                    exchange.getMessage().setBody("Cannot start conversion without SSLSession");
                }
            });
        }
    });
