@ParameterizedTest
@MethodSource("getOpenApiVersions")
void testDefaultConsumesConfig(String openApiVersion) throws Exception {
    CamelContext context = new DefaultCamelContext();
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            restConfiguration().apiProperty("openapi.version", openApiVersion).apiProperty("api.default.consumes", "application/xml");
            rest("/api").post("/test").param().name("body").description("The request body").type(RestParamType.body).endParam().to("direct:api");
            from("direct:api").setBody().constant("Hello World");
        }
    });
    RestConfiguration restConfiguration = context.getRestConfiguration();
    RestOpenApiProcessor processor = new RestOpenApiProcessor(restConfiguration.getApiProperties(), restConfiguration);
    processor.setCamelContext(context);
    processor.start();
    Exchange exchange = new DefaultExchange(context);
    processor.process(exchange);
    String json = exchange.getMessage().getBody(String.class);
    assertNotNull(json);
    log.info(json);
    JsonNode root = MAPPER.readTree(json);
    assertConsumesMatches(root, openApiVersion, "application/xml");
}

