    CamelContext context = createCamelContext(authenticationConfig -> {
        authenticationConfig.setEnabled(true);
        AuthenticationConfigEntry entry = new AuthenticationConfigEntry();
        entry.setAuthenticationProviderFactory(vertx -> PropertyFileAuthentication.create(vertx, "camel-platform-http-vertx-auth.properties"));
        entry.setAuthenticationHandlerFactory(BasicAuthHandler::create);
        entry.setPath("/*");
        authenticationConfig.getEntries().add(entry);
    });
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            from("platform-http:/defaultAuth").setBody().constant("defaultAuth");
        }
    });
    try {
        context.start();
        given().when().get("/defaultAuth").then().statusCode(401).body(equalTo("Unauthorized"));
        given().auth().basic("camel", "propertiesPass").when().get("/defaultAuth").then().statusCode(200).body(equalTo("defaultAuth"));
    } finally {
        context.stop();
    }
}

