// add a cookie with specified CookieConfiguration properties
@Test
public void testAddCookieCustomConfiguration() throws Exception {
    CamelContext context = createCamelContext();
    // 1 week
    long cookieMaxAge = 60L * 60 * 24 * 7;
    context.getRegistry().bind("cookieConfiguration", new CookieConfiguration.Builder().setPath("/testpath").setDomain("apache.org").setHttpOnly(true).setSecure(true).setMaxAge(cookieMaxAge).setSameSite(CookieConfiguration.CookieSameSite.STRICT).build());
    try {
        context.addRoutes(new RouteBuilder() {

            @Override
            public void configure() {
                from("platform-http:/add/custom?useCookieHandler=true&cookieConfiguration=#cookieConfiguration").process(exchange -> {
