            }
        });
        context.start();
        given().when().get("/add/custom").then().statusCode(200).cookie("foo", detailedCookie().value("bar").path("/testpath").domain("apache.org").secured(true).httpOnly(true).maxAge(cookieMaxAge).sameSite("Strict")).body(equalTo("add-custom"));
    } finally {
        context.stop();
    }
}

// get a cookie value from the cookieJar
@Test
public void testGetCookieValue() throws Exception {
    CamelContext context = createCamelContext();
    try {
        context.addRoutes(new RouteBuilder() {

            @Override
            public void configure() {
                from("platform-http:/get?useCookieHandler=true").process(exchange -> {
                    // write cookie name/value as a header so we can verify it was read
                    String cookieName = "foo";
                    String cookieVal = getCookieHandler(exchange).getCookieValue(cookieName);
                    exchange.getMessage().setHeader("cookie_name_val", String.format("%s=%s", cookieName, cookieVal));
                }).setBody().constant("get");
            }
        });
        context.start();
        given().header("cookie", "foo=bar").when().get("/get").then().statusCode(200).header("cookie_name_val", // verify cookie read
        "foo=bar").body(equalTo("get"));
    } finally {
        context.stop();
    }
}

