            from("platform-http:/secure").process(exchange -> {
                Message message = exchange.getMessage();
                message.setBody("Received message with the Authorization=" + exchange.getMessage().getHeader("Authorization"));
                User user = message.getHeader(VertxPlatformHttpConstants.AUTHENTICATED_USER, User.class);
                assertThat(user).isNotNull();
                JsonObject principal = user.principal();
                assertThat(principal).isNotNull();
                assertThat(principal.getString("username")).isEqualTo("camel");
            });
        }
    });
    context.getRegistry().bind("vertx", vertx);
    try {
        context.start();
        VertxPlatformHttpRouter router = VertxPlatformHttpRouter.lookup(context, VertxPlatformHttpRouter.getRouterNameFromPort(RestAssured.port));
        router.route().order(0).handler(basicAuthHandler);
        RestAssured.get("/secure").then().statusCode(401);
        RestAssured.given().auth().basic("camel", "s3cr3t").get("/secure").then().statusCode(200).body(is("Received message with the Authorization=Basic " + Base64.encodeBase64String("camel:s3cr3t".getBytes())));
    } finally {
        context.stop();
        vertx.close();
    }
}

