    assertEquals(PQCSymmetricAlgorithms.AES.getAlgorithm(), resultSign.getExchanges().get(0).getMessage().getBody(SecretKeyWithEncapsulation.class).getAlgorithm());
    SecretKeyWithEncapsulation secEncrypted = resultSign.getExchanges().get(0).getMessage().getBody(SecretKeyWithEncapsulation.class);
    assertNotNull(resultVerify.getExchanges().get(0).getMessage().getBody(SecretKeyWithEncapsulation.class));
    assertEquals(PQCSymmetricAlgorithms.AES.getAlgorithm(), resultVerify.getExchanges().get(0).getMessage().getBody(SecretKeyWithEncapsulation.class).getAlgorithm());
    SecretKeyWithEncapsulation secEncryptedExtracted = resultVerify.getExchanges().get(0).getMessage().getBody(SecretKeyWithEncapsulation.class);
    assertTrue(Arrays.areEqual(secEncrypted.getEncoded(), secEncryptedExtracted.getEncoded()));
}

