    from = context.getEndpoint("pulsar:" + topicName + "?numberOfConsumers=1&subscriptionType=Exclusive" + "&subscriptionName=camel-subscription&consumerQueueSize=" + consumerQueueSize + "&consumerName=camel-consumer&allowManualAcknowledgement=true");
