@Test
public void testDropStrategy() throws Exception {
    getReactiveStreamsComponent().setBackpressureStrategy(ReactiveStreamsBackpressureStrategy.OLDEST);
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            from("timer:gen?period=20&repeatCount=20&includeMetadata=true").setBody().header(Exchange.TIMER_COUNTER).to("reactive-streams:integers");
        }
    });
    final ConcurrentLinkedQueue<Integer> queue = new ConcurrentLinkedQueue<>();
    final CountDownLatch latch = new CountDownLatch(1);
    final CountDownLatch latch2 = new CountDownLatch(2);
    TestSubscriber<Integer> subscriber = new TestSubscriber<Integer>() {

        @Override
        public void onNext(Integer o) {
            queue.add(o);
            latch.countDown();
            latch2.countDown();
        }
    };
    subscriber.setInitiallyRequested(1);
    crs.fromStream("integers", Integer.class).subscribe(subscriber);
    context.start();
    assertTrue(latch.await(5, TimeUnit.SECONDS));
    // wait for all numbers to be generated
    Thread.sleep(1000);
    subscriber.request(19);
    assertTrue(latch2.await(1, TimeUnit.SECONDS));
    // add other time to ensure no other items arrive
    Thread.sleep(200);
    assertEquals(2, queue.size());
    int sum = queue.stream().reduce(Integer::sum).get();
    // 1 + 2 = 3
    assertEquals(3, sum);
    subscriber.cancel();
}

