@Test
public void testStreaming() throws Exception {
    final CountDownLatch latch1 = new CountDownLatch(1);
    final CountDownLatch latch2 = new CountDownLatch(1);
    // use background thread to write to stream that camel-servlet uses as reponse
    context.getExecutorServiceManager().newSingleThreadExecutor(this, "writer").execute(() -> {
        try {
            LOG.info(">>>> sleeping <<<<");
            Thread.sleep(500);
            LOG.info(">>>> writing <<<<");
            pos.write("ABC".getBytes());
            pos.flush();
            latch1.await(5, TimeUnit.SECONDS);
            LOG.info(">>>> sleeping <<<<");
            Thread.sleep(500);
            LOG.info(">>>> writing <<<<");
            pos.write("DEF".getBytes());
            pos.flush();
            latch2.await(5, TimeUnit.SECONDS);
            LOG.info(">>>> sleeping <<<<");
            Thread.sleep(500);
            LOG.info(">>>> writing <<<<");
            pos.write("GHI".getBytes());
            pos.flush();
        } catch (Exception e) {
            // ignore
        } finally {
            LOG.info(">>>> closing <<<<");
            IOHelper.close(pos);
        }
    });
    LOG.info(">>>> calling <<<<");
    WebRequest req = new GetMethodWebRequest(contextUrl + "/services/hello");
    WebResponse response = query(req);
    LOG.info(">>>> response <<<<");
    assertEquals(200, response.getResponseCode());
    assertEquals("chunked", response.getHeaderField(Exchange.TRANSFER_ENCODING));
    InputStream is = response.getInputStream();
    assertNotNull(is);
    LOG.info(">>>> reading chunk1 <<<<");
    int ch1 = is.read();
    int ch2 = is.read();
    int ch3 = is.read();
    LOG.info(">>>> reading chunk1 complete <<<<");
    assertEquals('A', ch1);
    assertEquals('B', ch2);
    assertEquals('C', ch3);
    latch1.countDown();
    LOG.info(">>>> reading chunk2 <<<<");
    int ch4 = is.read();
    int ch5 = is.read();
    int ch6 = is.read();
    LOG.info(">>>> reading chunk2 complete <<<<");
    assertEquals('D', ch4);
    assertEquals('E', ch5);
    assertEquals('F', ch6);
    latch2.countDown();
    LOG.info(">>>> reading chunk3 <<<<");
    int ch7 = is.read();
    int ch8 = is.read();
    int ch9 = is.read();
    LOG.info(">>>> reading chunk3 complete <<<<");
    assertEquals('G', ch7);
    assertEquals('H', ch8);
    assertEquals('I', ch9);
    int end = is.read();
    LOG.info(">>>> reading EOS <<<<");
    assertEquals(-1, end);
}

@Test
public void testManual() throws Exception {
    LOG.info("Sleeping 10 sec");
    Thread.sleep(10000);
    // use background thread to write to stream that camel-servlet uses as response
    context.getExecutorServiceManager().newSingleThreadExecutor(this, "writer").execute(() -> {
        try {
            File file = new File("src/test/data/big-payload.json");
            FileInputStream fis = new FileInputStream(file);
            LOG.info(">>>> sleeping <<<<");
            Thread.sleep(1000);
            LOG.info(">>>> writing <<<<");
            int ch = 0;
            int len = 0;
            while (ch != -1) {
                ch = fis.read();
                pos.write(ch);
                len++;
                if (len % 1000 == 0) {
                    LOG.info(">>>> sleeping <<<<");
                    pos.flush();
                    Thread.sleep(250);
                    LOG.info(">>>> writing <<<<");
                }
            }
            LOG.info(">>>> Payload size: {}", len);
            LOG.info(">>>> writing EOL <<<<");
            pos.flush();
        } catch (Exception e) {
            // ignore
        } finally {
            LOG.info(">>>> closing <<<<");
            IOHelper.close(pos);
        }
    });
    LOG.info("Sleeping 60 sec");
    Thread.sleep(60000);
}

