    MockEndpoint mock = context.getEndpoint("mock:reverse", MockEndpoint.class);
    assertNotNull(mock);
    mock.expectedMessageCount(0);
    try (InputStream is = this.getClass().getClassLoader().getResourceAsStream("data-dos.yaml")) {
        ProducerTemplate template = context.createProducerTemplate();
        Exception ex = assertThrows(CamelExecutionException.class, () -> template.requestBody("direct:back", is, String.class), "Failure expected on an alias expansion attack");
