@Test
void testIfCreateBatch() throws Exception {
    final StitchClient client = StitchClientBuilder.builder().withRegion(StitchRegion.EUROPE).withToken(StitchTestUtils.loadStitchTokenFromJvmEnv().getProperty("token")).build();
    final StitchMessage message1 = StitchMessage.builder().withData("id", 2).withData("name", "Jake").withData("age", 6).withData("has_magic", true).withSequence(1565881320).build();
    final Map<String, Object> properties = new LinkedHashMap<>();
    properties.put("id", Collections.singletonMap("type", "integer"));
    properties.put("name", Collections.singletonMap("type", "string"));
    properties.put("age", Collections.singletonMap("type", "integer"));
    properties.put("has_magic", Collections.singletonMap("type", "boolean"));
    final StitchSchema schema = StitchSchema.builder().addKeyword("properties", properties).build();
    final StitchRequestBody body = StitchRequestBody.builder().withTableName("test").addMessage(message1).withSchema(schema).withKeyNames("id").build();
    StitchResponse response = client.batch(body).block();
    assertNotNull(response);
    assertEquals(201, response.getHttpStatusCode());
}

