@Test
void testIfCreateNormalMessage() {
    final StitchMessage message = StitchMessage.builder().withData("id", 2).withData("name", "Jake").withData("age", 6).withData("has_magic", true).withData("modified_at", "2020-01-13T21:25:03+0000").withSequence(1565881320).withAction(StitchMessage.Action.UPSERT).build();
    final String messageAsJson = JsonUtils.convertMapToJson(message.toMap());
    assertEquals("{\"action\":\"upsert\",\"sequence\":1565881320,\"data\":" + "{\"id\":2,\"name\":\"Jake\",\"age\":6,\"has_magic\":true,\"modified_at\":\"2020-01-13T21:25:03+0000\"}}", messageAsJson);
}

@Test
void testIfNotCreateFromMapFromInvalidData() {
    final LinkedHashMap<String, Object> data = new LinkedHashMap<>();
    data.put(StitchMessage.ACTION, "upsert");
    data.put(StitchMessage.DATA, 1);
    data.put(StitchMessage.SEQUENCE, 1122544L);
    assertThrows(IllegalArgumentException.class, () -> StitchMessage.fromMap(data));
}

@Test
void testIfCreateMap() {
    final Map<String, Object> data = new LinkedHashMap<>();
    data.put("id", 2);
    data.put("name", "Jake");
    final Map<String, Object> message = new LinkedHashMap<>();
    message.put(StitchMessage.SEQUENCE, 123456L);
    message.put(StitchMessage.DATA, data);
    final StitchMessage stitchMessage = StitchMessage.fromMap(message).build();
    assertEquals(StitchMessage.Action.UPSERT, stitchMessage.getAction());
    assertEquals(data, stitchMessage.getData());
    assertEquals(123456L, stitchMessage.getSequence());
}

@Test
public void testNormalRequestBodyToJson() throws JsonProcessingException {
    final StitchMessage message1 = StitchMessage.builder().withData("id", 2).withData("name", "Jake").withData("age", 6).withData("has_magic", true).withData("modified_at", "2020-01-13T21:25:03+0000").withSequence(1565881320).build();
    final StitchMessage message2 = StitchMessage.builder().withData("id", 3).withData("name", "Bubblegum").withData("age", 17).withData("has_magic", true).withData("modified_at", "2020-01-14T13:34:25+0000").withSequence(1565838645).build();
    final Map<String, String> modifiedAtSchema = new LinkedHashMap<>();
    modifiedAtSchema.put("type", "string");
    modifiedAtSchema.put("format", "date-time");
    final Map<String, Object> properties = new LinkedHashMap<>();
    properties.put("id", Collections.singletonMap("type", "integer"));
