@Test
void testSplitter() throws Exception {
    MockEndpoint mock = getMockEndpoint("mock:aggregateToTarEntry");
    mock.expectedMessageCount(1);
    template.setDefaultEndpointUri("direct:start");
    template.sendBodyAndHeader("foo", Exchange.FILE_NAME, FILE_NAMES.get(0));
    template.sendBodyAndHeader("bar", Exchange.FILE_NAME, FILE_NAMES.get(1));
    MockEndpoint.assertIsSatisfied(context);
    await("Should be a file in target/out directory").until(() -> {
        File[] files = new File("target/out").listFiles();
        return files != null && files.length > 0;
    });
    File[] files = new File("target/out").listFiles();
    File resultFile = files[0];
    final TarArchiveInputStream tis = new ArchiveStreamFactory().createArchiveInputStream(ArchiveStreamFactory.TAR, new BufferedInputStream(new FileInputStream(resultFile)));
    try {
        int fileCount = 0;
        for (TarArchiveEntry entry = tis.getNextEntry(); entry != null; entry = tis.getNextEntry()) {
            fileCount++;
            assertTrue(FILE_NAMES.contains(entry.getName()), "Tar entry file name should be on of: " + FILE_NAMES);
        }
        assertEquals(FILE_NAMES.size(), fileCount, "Tar file should contain " + FILE_NAMES.size() + " files");
    } finally {
        IOHelper.close(tis);
    }
}

@Test
void testSplitter() throws Exception {
    MockEndpoint mock = getMockEndpoint("mock:aggregateToTarEntry");
    mock.expectedMessageCount(1);
    MockEndpoint.assertIsSatisfied(context);
    await("Should be a file in target/out directory").until(() -> {
        File[] files = new File("target/out").listFiles();
        return files != null && files.length > 0;
    });
    File[] files = new File("target/out").listFiles();
    File resultFile = files[0];
    Set<String> expectedTarFiles = new HashSet<>(Arrays.asList("another/hello.txt", "other/greetings.txt", "chiau.txt", "hi.txt", "hola.txt"));
    TarArchiveInputStream tin = new TarArchiveInputStream(new FileInputStream(resultFile));
    try {
        int fileCount = 0;
        for (TarArchiveEntry te = tin.getNextEntry(); te != null; te = tin.getNextEntry()) {
            String name = te.getName();
            if (expectedTarFiles.contains(name)) {
                expectedTarFiles.remove(te.getName());
            } else {
                fail("Unexpected name in tarfile: " + name);
            }
            fileCount++;
        }
        assertEquals(AggregationStrategyWithPreservationTest.EXPECTED_NO_FILES, fileCount, "Tar file should contains " + AggregationStrategyWithPreservationTest.EXPECTED_NO_FILES + " files");
        assertEquals(0, expectedTarFiles.size(), "Should have found all of the tar files in the file.");
    } finally {
        IOHelper.close(tin);
    }
}

