    SpanAdapter parent = MockSpanAdapter.buildSpan("parent");
    ActiveSpanManager.activate(exchange, parent);
    SpanAdapter child = MockSpanAdapter.buildSpan("child");
    ActiveSpanManager.activate(exchange, child);
