@Test
public void invalidXmlFragmentForClaimedRole() throws Exception {
    MockEndpoint mock = getMockEndpoint("mock:exception");
    mock.expectedMessageCount(1);
    XmlSignerEndpoint endpoint = getSignerEndpoint();
    XAdESSignatureProperties props = (XAdESSignatureProperties) endpoint.getConfiguration().getProperties();
    // Element 'ClaimedRole' is not closed correctly
    props.setSignerClaimedRoles(Collections.singletonList("<ClaimedRole>wrong XML fragment<ClaimedRole>"));
    sendBody("direct:enveloping", payload, Collections.emptyMap());
    MockEndpoint.assertIsSatisfied(context);
    checkThrownException(mock, XmlSignatureException.class, "The XAdES configuration is invalid. The list of the claimed roles contains the invalid entry '<ClaimedRole>wrong XML fragment<ClaimedRole>'. An entry must either be a text or" + " an XML fragment with the root element 'ClaimedRole' with the namespace 'http://uri.etsi.org/01903/v1.3.2#'.", null);
}

