@Test
public void allOperationValuesShouldBeListedInOperationNameUriPath() throws NoSuchFieldException, SecurityException {
    UriPath uriPath = ZeebeEndpoint.class.getDeclaredField("operationName").getAnnotation(UriPath.class);
    String[] operationNamesInAnnotation = uriPath.enums().split(",");
    Arrays.sort(operationNamesInAnnotation);
    String[] operationNamesInEnum = Arrays.stream(OperationName.values()).map(OperationName::value).toArray(length -> new String[length]);
    Arrays.sort(operationNamesInEnum);
    assertArrayEquals(operationNamesInEnum, operationNamesInAnnotation, "All operation values, the String value returned from OperationName::value, must be defined in the @UriPath " + "enum parameter of the operationName field in ZeebeEndpoint, set the enums parameter to:\n" + Arrays.stream(operationNamesInEnum).collect(Collectors.joining(",")));
}

