@Test
public void testSplitter() throws Exception {
    MockEndpoint mock = getMockEndpoint("mock:aggregateToZipEntry");
    mock.expectedMessageCount(1);
    template.setDefaultEndpointUri("direct:start");
    template.sendBodyAndHeader("foo", Exchange.FILE_NAME, FILE_NAMES.get(0));
    template.sendBodyAndHeader("bar", Exchange.FILE_NAME, FILE_NAMES.get(1));
    MockEndpoint.assertIsSatisfied(context);
    File[] files = new File(TEST_DIR).listFiles();
    assertNotNull(files);
    assertTrue(files.length > 0, "Should be a file in " + TEST_DIR + " directory");
    File resultFile = files[0];
    final ZipFile file = new ZipFile(resultFile);
    try {
        final Enumeration<? extends ZipEntry> entries = file.entries();
        int fileCount = 0;
        while (entries.hasMoreElements()) {
            fileCount++;
            final ZipEntry entry = entries.nextElement();
            assertTrue(FILE_NAMES.contains(entry.getName()), "Zip entry file name should be on of: " + FILE_NAMES);
        }
        assertEquals(FILE_NAMES.size(), fileCount, "Zip file should contain " + FILE_NAMES.size() + " files");
    } finally {
        IOHelper.close(file);
    }
}

@Test
public void testSplitter() throws Exception {
    MockEndpoint mock = getMockEndpoint("mock:aggregateToZipEntry");
    mock.expectedMessageCount(1);
    MockEndpoint.assertIsSatisfied(context);
    File[] files = new File(TEST_DIR).listFiles();
    assertNotNull(files);
    assertTrue(files.length > 0, "Should be a file in " + TEST_DIR + " directory");
    File resultFile = files[0];
    Set<String> expectedZipFiles = new HashSet<>(Arrays.asList("another/hello.txt", "other/greetings.txt", "chiau.txt", "hi.txt", "hola.txt"));
    ZipInputStream zin = new ZipInputStream(new FileInputStream(resultFile));
    try {
        int fileCount = 0;
        for (ZipEntry ze = zin.getNextEntry(); ze != null; ze = zin.getNextEntry()) {
            if (!ze.isDirectory()) {
                assertTrue(expectedZipFiles.remove(ze.toString()), "Found unexpected entry " + ze + " in zipfile");
                fileCount++;
            }
        }
        assertEquals(AggregationStrategyWithPreservationTest.EXPECTED_NO_FILES, fileCount, String.format("Zip file should contains %d files, got %d files", AggregationStrategyWithPreservationTest.EXPECTED_NO_FILES, fileCount));
        assertEquals(0, expectedZipFiles.size(), "Should have found all of the zip files in the file. Remaining: " + expectedZipFiles);
    } finally {
        IOHelper.close(zin);
    }
}

