@Test
void testServiceDiscovery() throws Exception {
    try (CuratorFramework curatorFramework = CuratorFrameworkFactory.builder().connectString(service.getConnectionString()).retryPolicy(new ExponentialBackoffRetry(1000, 3)).build()) {
        ZooKeeperCuratorConfiguration configuration = new ZooKeeperCuratorConfiguration();
        configuration.setBasePath("/camel");
        configuration.setCuratorFramework(curatorFramework);
        try (ServiceDiscovery<MetaData> zkDiscovery = ZooKeeperCuratorHelper.createServiceDiscovery(configuration, curatorFramework, MetaData.class)) {
            curatorFramework.start();
            zkDiscovery.start();
            List<ServiceInstance<MetaData>> instances = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                ServiceInstance<MetaData> instance = ServiceInstance.<MetaData>builder().address("127.0.0.1").port(AvailablePortFinder.getNextRandomAvailable()).name("my-service").id("service-" + i).build();
                zkDiscovery.registerService(instance);
                instances.add(instance);
            }
            try (ZooKeeperServiceDiscovery discovery = new ZooKeeperServiceDiscovery(configuration)) {
                discovery.start();
                await().atMost(1, TimeUnit.MINUTES).untilAsserted(() -> assertEquals(3, discovery.getServices("my-service").size()));
                List<ServiceDefinition> services = discovery.getServices("my-service");
                assertNotNull(services);
                assertEquals(3, services.size());
                for (ServiceDefinition service : services) {
                    assertEquals(1, instances.stream().filter(i -> i.getPort() == service.getPort() && i.getAddress().equals(service.getHost()) && i.getId().equals(service.getMetadata().get(ServiceDefinition.SERVICE_META_ID)) && i.getName().equals(service.getName())).count());
                }
            }
        }
    }
}

@Test
public void testRegistrationFromRoute() throws Exception {
    // the service should not be registered as the route is not running
    assertTrue(discovery.queryForInstances(SERVICE_NAME).isEmpty());
    // let start the route
    context().getRouteController().startRoute(SERVICE_ID);
    // check that service has been registered
    await().atMost(2, TimeUnit.MINUTES).untilAsserted(() -> assertEquals(1, discovery.queryForInstances(SERVICE_NAME).size()));
    Collection<ServiceInstance<MetaData>> services = discovery.queryForInstances(SERVICE_NAME);
    ServiceInstance<MetaData> instance = services.iterator().next();
    assertEquals(SERVICE_PORT, (int) instance.getPort());
    assertEquals("localhost", instance.getAddress());
    assertEquals("http", instance.getPayload().get(ServiceDefinition.SERVICE_META_PROTOCOL));
    assertEquals("/service/endpoint", instance.getPayload().get(ServiceDefinition.SERVICE_META_PATH));
    getMetadata().forEach((k, v) -> {
        assertEquals(v, instance.getPayload().get(k));
    });
    // let stop the route
    context().getRouteController().stopRoute(SERVICE_ID);
    // the service should be removed once the route is stopped
    await().atMost(2, TimeUnit.MINUTES).untilAsserted(() -> assertTrue(discovery.queryForInstances(SERVICE_NAME).isEmpty()));
}

