@Test
public void testDefineRouteTemplate() throws Exception {
    try (DefaultCamelContext context = new DefaultCamelContext()) {
        context.getCamelContextExtension().getRegistry().bind("myErrorHandler", new NoErrorHandlerDefinition());
        context.addRoutes(new RouteBuilder() {

            @Override
            public void configure() {
                errorHandler("myErrorHandler");
                routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar").from("direct:{{foo}}").to("mock:{{bar}}");
                from("direct:_r").to("mock:_r");
            }
        });
        assertThat(context.getRouteDefinitions()).first().satisfies(d -> {
            assertThat(d.getErrorHandlerFactory()).isInstanceOfSatisfying(RefErrorHandlerDefinition.class, h -> {
                assertThat(h.getRef()).isEqualTo("myErrorHandler");
            });
        });
        assertThat(context.getRouteTemplateDefinitions()).first().satisfies(d -> {
            assertThat(d.route().getErrorHandlerFactory()).isInstanceOfSatisfying(RefErrorHandlerDefinition.class, h -> {
                assertThat(h.getRef()).isEqualTo("myErrorHandler");
            });
        });
        context.addRouteFromTemplate("myId", "myTemplate", mapOf("foo", "f", "bar", "b"));
        context.start();
        assertThat(context.getRoutes()).allSatisfy(r -> {
            assertThat(r).isInstanceOfSatisfying(DefaultRoute.class, dr -> {
                Channel channel = unwrapChannel(r.getProcessor());
                assertThat(channel).isNotNull();
                assertThat(channel.getErrorHandler()).isInstanceOf(NoErrorHandler.class);
            });
        });
    }
}

@Test
public void testCreateRouteFromRouteTemplate() throws Exception {
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar").from("direct:{{foo}}").to("mock:{{bar}}");
            RouteConfigurationDefinition routeConfigurationDefinition = new RouteConfigurationDefinition();
            routeConfigurationDefinition.interceptFrom("direct:intercepted-from").to("mock:intercepted-from");
            routeConfigurationDefinition.interceptSendToEndpoint("mock:intercepted-send").to("mock:intercepted-send-to-before").afterUri("mock:intercepted-send-to-after");
            context.addRouteConfiguration(routeConfigurationDefinition);
        }
    });
    assertEquals(1, context.getRouteTemplateDefinitions().size());
    RouteTemplateDefinition routeTemplate = context.getRouteTemplateDefinition("myTemplate");
    assertEquals("foo", routeTemplate.getTemplateParameters().get(0).getName());
    assertEquals("bar", routeTemplate.getTemplateParameters().get(1).getName());
    for (String uriSuffix : Arrays.asList("from", "send-to-before", "send-to-after")) {
        getMockEndpoint("mock:intercepted-" + uriSuffix).expectedBodiesReceived("Hello Intercepted");
    }
    TemplatedRouteBuilder.builder(context, "myTemplate").routeId("intercepted").parameter("foo", "intercepted-from").parameter("bar", "intercepted-send").add();
    // now start camel
    context.start();
    assertEquals(1, context.getRouteDefinitions().size());
    assertEquals(1, context.getRoutes().size());
    assertEquals("Started", context.getRouteController().getRouteStatus("intercepted").name());
    assertEquals("true", context.getRoute("intercepted").getProperties().get(Route.TEMPLATE_PROPERTY));
    template.sendBody("direct:intercepted-from", "Hello Intercepted");
    assertMockEndpointsSatisfied();
    context.stop();
}

@Test
public void testGlobalBean() throws Exception {
    context.getRegistry().bind("myBar", (Processor) ex -> ex.getMessage().setBody("Global " + ex.getMessage().getBody()));
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            routeTemplate("myTemplate").templateParameter("foo").templateParameter("bar").from("direct:{{foo}}").to("bean:{{bar}}");
        }
    });
    context.start();
    TemplatedRouteBuilder.builder(context, "myTemplate").parameter("foo", "one").parameter("bar", "myBar").routeId("myRoute").add();
    assertEquals(1, context.getRoutes().size());
    Object out = template.requestBody("direct:one", "World");
    assertEquals("Global World", out);
    // should be a global bean
    assertNotNull(context.getRegistry().lookupByName("myBar"));
    context.stop();
}

