@Test
public void testAsEndpointUriSecrets() throws Exception {
    // create a custom instance of the catalog to hack the model to post
    // process options.
    RuntimeCamelCatalog catalog = new DefaultRuntimeCamelCatalog() {

        @Override
        public ComponentModel componentModel(String name) {
            ComponentModel model = super.componentModel(name);
            if (model != null && "timer".equals(name)) {
                model.getEndpointParameterOptions().stream().filter(o -> Objects.equals(o.getName(), "period")).forEach(o -> o.setSecret(true));
                model.getEndpointPathOptions().stream().filter(o -> Objects.equals(o.getName(), "timerName")).forEach(o -> o.setDefaultValue("defaultName"));
            }
            return model;
        }
    };
    catalog.setCamelContext(new DefaultCamelContext());
    assertEquals("timer:foo?period=RAW(5000)", catalog.asEndpointUri("timer", mapOf("timerName", "foo", "period", "5000"), false));
    assertEquals("timer:defaultName?period=RAW(5000)", catalog.asEndpointUri("timer", mapOf("period", "5000"), false));
}

