@Test
public void testConsumerTemplateCreateBodyAlwaysException() {
    final AtomicBoolean fail = new AtomicBoolean();
    template.send("seda:empty", e -> {
        e.setIn(new DefaultMessage(e) {

            @Override
            protected Object createBody() {
                if (fail.get()) {
                    throw new IllegalArgumentException("Forced internal error");
                } else {
                    return null;
                }
            }

            @Override
            public DefaultMessage newInstance() {
                // dont copy so we can preserve this message instance that has the fail mode in createBody
                return this;
            }
        });
    });
    // turn on fail mode
    fail.set(true);
    Exception e = assertThrows(Exception.class, () -> consumer.receiveBody("seda:empty", 1000), "Should throw exception");
    assertIsInstanceOf(IllegalArgumentException.class, e);
    assertEquals("Forced internal error", e.getMessage());
    fail.set(false);
    assertDoesNotThrow(() -> consumer.receiveBody("seda:empty", 1000), "");
}

