@Test
public void testDirect() throws Exception {
    CamelContext container = new DefaultCamelContext();
    final AtomicBoolean invoked = new AtomicBoolean();
    // lets add some routes
    container.addRoutes(new RouteBuilder() {

        public void configure() {
            from("direct:test.a").to("direct:test.b");
            from("direct:test.b?synchronous=true").process(new Processor() {

                public void process(Exchange e) {
                    invoked.set(true);
                }
            });
            from("direct:test.c").to("direct:test.d?synchronous=true");
            from("direct:test.d").process(new Processor() {

                public void process(Exchange e) {
                    invoked.set(true);
                }
            });
        }
    });
    container.start();
    // now lets fire in a message
    Endpoint endpoint = container.getEndpoint("direct:test.a");
    Exchange exchange = endpoint.createExchange();
    exchange.getIn().setHeader("cheese", 123);
    Producer producer = endpoint.createProducer();
    producer.process(exchange);
    // now lets sleep for a while
    assertTrue(invoked.get(), "Did not receive the message!");
    invoked.set(false);
    // now lets fire in a message
    endpoint = container.getEndpoint("direct:test.c");
    exchange = endpoint.createExchange();
    exchange.getIn().setHeader("cake", 456);
    producer = endpoint.createProducer();
    producer.process(exchange);
    // now lets sleep for a while
    assertTrue(invoked.get(), "Did not receive the message!");
    container.stop();
}

