@Test
public void testPollingConsumer() throws Exception {
    template.sendBodyAndHeader(fileUri(), "Hello World", Exchange.FILE_NAME, "hello.txt");
    PollingConsumer consumer = context.getEndpoint(fileUri()).createPollingConsumer();
    consumer.start();
    Exchange exchange = consumer.receive(5000);
    assertNotNull(exchange);
    assertEquals("Hello World", exchange.getIn().getBody(String.class));
    // sleep a bit to ensure polling consumer would be suspended after we
    // have used it
    Awaitility.await().pollDelay(500, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertDoesNotThrow(() -> template.sendBodyAndHeader(fileUri(), "Bye World", Exchange.FILE_NAME, "bye.txt")));
    // sleep a bit to ensure polling consumer would not have picked up that
    // file
    Awaitility.await().pollDelay(1000, TimeUnit.MILLISECONDS).untilAsserted(() -> assertTrue(Files.exists(testFile("bye.txt")), "File should exist bye.txt"));
    consumer.stop();
}

