@DisplayName("Tests that an exception will be thrown if allowNullBody is absent and a null body is sent")
public void testAllowNullBodyFalse() {
    CamelExecutionException e = assertThrows(CamelExecutionException.class, () -> template.sendBody(fileUri("?fileName=allowNullBody.txt"), null), "Should have thrown a GenericFileOperationFailedException");
