@Test
public void testSortFiles() throws Exception {
    prepareFolder("a");
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            from(fileUri("a/?initialDelay=0&delay=10&sortBy=file:ext")).to("mock:result");
