    // this is. As we want to optimize PropertyEditorTypeConverter to be
    // faster
    MyBean bean = new MyBean();
    bean.setBar("Hello");
    StopWatch watch = new StopWatch();
    for (int i = 0; i < 500; i++) {
        String s = context.getTypeConverter().convertTo(String.class, bean);
        log.debug(s);
        assertNotNull(s);
