@DisplayName("Test that the configurer uses the ContextConfigurer wrapper for the CamelContext and subclasses")
@Test
void resolvePropertyConfigurerShouldFallbackToDefaultConfigurer() {
    Stream.of(CamelContext.class.getName(), SimpleCamelContext.class.getName(), "org.apache.camel.model.ModelCamelContext", "org.apache.camel.SomeCamelContextStuff").forEach(name -> assertThat(resolver.resolvePropertyConfigurer(name, ctx)).as(name).isInstanceOf(DefaultConfigurerResolver.ContextConfigurer.class));
