@Test
public void testCopy() throws Exception {
    PollingConsumer pc = context.getEndpoint("direct:foo?pollingConsumerCopy=true").createPollingConsumer();
    pc.start();
    context.addRoutes(new RouteBuilder() {

        @Override
        public void configure() {
            from("direct:start").process(new Processor() {

                @Override
                public void process(Exchange exchange) {
                    exchange.getUnitOfWork().addSynchronization(new SynchronizationAdapter() {

                        @Override
                        public void onDone(Exchange exchange) {
                            done.set(true);
                        }
                    });
                }
            }).to("direct:foo").to("mock:result");
        }
    });
    context.start();
    // should be 0 inflight
    assertEquals(0, context.getInflightRepository().size());
    getMockEndpoint("mock:result").expectedMessageCount(1);
    template.sendBody("direct:start", "Hello World");
    assertMockEndpointsSatisfied();
    Exchange original = getMockEndpoint("mock:result").getExchanges().get(0);
    assertNotNull(original);
    assertFalse(done.get(), "UoW should be handed over");
    Exchange polled = pc.receive(1000);
    assertNotNull(polled);
    assertEquals("Hello World", polled.getMessage().getBody());
    assertNotEquals(polled.getExchangeId(), original.getExchangeId());
    // should be 1 inflight
    assertEquals(1, context.getInflightRepository().size());
    // done uow
    polled.getUnitOfWork().done(polled);
    assertTrue(done.get(), "UoW should be done now");
    // should be 0 inflight
    assertEquals(0, context.getInflightRepository().size());
    pc.stop();
    context.stop();
}

@Test
public void testQueueSize() throws Exception {
    // must start context as we do not use route builder that auto-start
    context.start();
    PollingConsumer consumer = context.getEndpoint(uri).createPollingConsumer();
    consumer.start();
    assertNotNull(consumer);
    EventDrivenPollingConsumer edpc = assertIsInstanceOf(EventDrivenPollingConsumer.class, consumer);
    assertEquals(0, edpc.getQueueSize());
    assertEquals(10, edpc.getQueueCapacity());
    assertFalse(edpc.isBlockWhenFull());
    for (int i = 0; i < 10; i++) {
        template.sendBody(uri, "Message " + i);
    }
    assertEquals(10, edpc.getQueueSize());
    CamelExecutionException e = assertThrows(CamelExecutionException.class, () -> template.sendBody(uri, "Message 10"), "Should have thrown exception");
    assertIsInstanceOf(IllegalStateException.class, e.getCause());
    Exchange out = consumer.receive(5000);
    assertNotNull(out);
    assertEquals("Message 0", out.getIn().getBody());
    assertEquals(9, edpc.getQueueSize());
    assertEquals(10, edpc.getQueueCapacity());
    // now there is room
    template.sendBody(uri, "Message 10");
    assertEquals(10, edpc.getQueueSize());
    assertEquals(10, edpc.getQueueCapacity());
    ServiceHelper.stopService(consumer);
    // not cleared if we stop
    assertEquals(10, edpc.getQueueSize());
    assertEquals(10, edpc.getQueueCapacity());
    ServiceHelper.stopAndShutdownService(consumer);
    // now its cleared as we shutdown
    assertEquals(0, edpc.getQueueSize());
    assertEquals(10, edpc.getQueueCapacity());
}

