            from("direct:receive").enrich().constant("direct:foo").variableReceive("bye").to("mock:result");
            from("direct:foo").transform().simple("Bye ${body}").doTry().throwException(new IllegalArgumentException("Forced")).doCatch(Exception.class).setBody(simple("Catch: ${body}")).end();
