public void testThrottlingRoutePolicyStartWithAlwaysOpenOn() throws Exception {
    log.debug("---- sending some messages");
    for (int i = 0; i < size; i++) {
        template.sendBody(url, "Message " + i);
        Thread.sleep(3);
    }
