    sendBody("foo", "mock:x");
    sendBody("foo", "mock:y");
    sendBody("foo", "mock:z");
    sendBody("bar", "mock:x");
    sendBody("bar", "mock:y");
    sendBody("bar", "mock:z");
    // should not register as new endpoint so we keep at 4
    sendBody("dummy", "mock:dummy");
    assertMockEndpointsSatisfied();
    assertEquals(4, context.getEndpointRegistry().size());
}

