    }
    byte[] buf = "\u00A31\n\u00A32\n".getBytes(StandardCharsets.UTF_8);
    ByteArrayInputStream in = new ByteArrayInputStream(buf);
    Scanner scanner = new Scanner(in, StandardCharsets.UTF_8.displayName(), "\n");
