    RouteWatcherReloadStrategy strategy = new RouteWatcherReloadStrategy("./src/test/resources/org/apache/camel/model");
    strategy.setPattern(null);
    strategy.setCamelContext(context);
    strategy.doStart();
    assertNotNull(strategy.getFileFilter());
    File folder = new File("./src/test/resources/org/apache/camel/model");
    assertTrue(folder.isDirectory());
    File[] fs = folder.listFiles(strategy.getFileFilter());
    assertNotNull(fs);
    assertTrue(fs.length >= 40, String.valueOf(fs.length));
    // null goes back to default
    assertEquals("*.yaml,*.xml", strategy.getPattern());
}

@Test
public void testServiceSupport() {
    MyService service = new MyService();
    service.start();
    assertTrue(service.isStarted());
    assertFalse(service.isStarting());
    assertFalse(service.isStopped());
    assertFalse(service.isStopping());
    service.stop();
    assertTrue(service.isStopped());
    assertFalse(service.isStopping());
    assertFalse(service.isStarted());
    assertFalse(service.isStarting());
}

@Test
public void testServiceSupportIsRunAllowed() {
    MyService service = new MyService();
    assertFalse(service.isRunAllowed());
    service.start();
    assertTrue(service.isRunAllowed());
    // we are allowed to run while suspending/suspended
    service.suspend();
    assertTrue(service.isRunAllowed());
    service.resume();
    assertTrue(service.isRunAllowed());
    // but if we are stopped then we are not
    service.stop();
    assertFalse(service.isRunAllowed());
    service.shutdown();
    assertFalse(service.isRunAllowed());
}

@Test
public void testServiceSupportShutdown() {
    MyShutdownService service = new MyShutdownService();
    service.start();
    assertTrue(service.isStarted());
    assertFalse(service.isStarting());
    assertFalse(service.isStopped());
    assertFalse(service.isStopping());
    assertFalse(service.isShutdown());
    service.shutdown();
    assertTrue(service.isStopped());
    assertFalse(service.isStopping());
    assertFalse(service.isStarted());
    assertFalse(service.isStarting());
    assertTrue(service.isShutdown());
}

@Test
public void testExceptionOnStart() {
    ServiceSupportTestExOnStart service = new ServiceSupportTestExOnStart();
    // forced not being stopped at start
    assertFalse(service.isStopped());
    try {
        service.start();
        fail("RuntimeException expected");
    } catch (RuntimeException e) {
        assertTrue(service.isStopped());
        assertFalse(service.isStopping());
        assertFalse(service.isStarted());
        assertFalse(service.isStarting());
    }
}

@Test
public void testServiceBuild() {
