        assertFalse(ObjectHelper.typeCoerceContains(tc, array, "xyz", true));
        assertFalse(ObjectHelper.typeCoerceContains(tc, collection, "xyz", true));
        assertFalse(ObjectHelper.typeCoerceContains(tc, "foo", "xyz", true));
    }
}

