@Test
public void testEventOrder() throws Exception {
    List<String> events = new ArrayList<>();
    Main main = new Main();
    main.addMainListener((MainListener) Proxy.newProxyInstance(MainListener.class.getClassLoader(), new Class[] { MainListener.class }, (proxy, method, args) -> {
        events.add(method.getName());
        return null;
    }));
    Thread thread = new Thread(() -> {
        try {
            main.run();
        } catch (Exception e) {
            fail("Unexpected exception: " + e);
        }
    });
    thread.start();
    Thread.sleep(100);
    main.completed();
    thread.join();
    assertEquals(Arrays.asList("beforeInitialize", "beforeConfigure", "afterConfigure", "beforeStart", "afterStart", "beforeStop", "afterStop"), events);
}

