        assertEquals("secretHello1", main.getCamelContext().resolvePropertyPlaceholders("{{my.secret.prop.1}}"));
        assertEquals("secretHello2", main.getCamelContext().resolvePropertyPlaceholders("{{my.secret.prop.2}}"));
    } finally {
