@Test
public void testChargeDischarge() {
    LoadTriplet t = new LoadTriplet();
    t.update(0);
    double last = t.getLoad15();
    double lastDiff = Double.MAX_VALUE;
    double diff;
    for (int i = 0; i < 1000; i++) {
        t.update(5);
        diff = t.getLoad15() - last;
        assertTrue(diff > 0.0);
        assertTrue(diff < lastDiff);
        lastDiff = diff;
        last = t.getLoad15();
    }
    lastDiff = -Double.MAX_VALUE;
    for (int i = 0; i < 1000; i++) {
        t.update(0);
        diff = t.getLoad15() - last;
        assertTrue(diff < 0.0);
        assertTrue(diff > lastDiff, String.format("%f is smaller than %f", diff, lastDiff));
        lastDiff = diff;
        last = t.getLoad15();
    }
}

