    template.sendBody("direct:start", "Hello World");
    template.sendBody("direct:start", "Bye World");
    assertMockEndpointsSatisfied();
    MBeanServer mbeanServer = getMBeanServer();
    ObjectName name = getCamelObjectName(TYPE_ENDPOINT, "mock://result");
    String uri = (String) mbeanServer.getAttribute(name, "EndpointUri");
    assertEquals("mock://result", uri);
    Integer size = (Integer) mbeanServer.invoke(name, "queueSize", null, null);
    assertEquals(2, size.intValue());
    String out = (String) mbeanServer.invoke(name, "browseExchange", new Object[] { 0 }, new String[] { "java.lang.Integer" });
    assertNotNull(out);
    // message body is not dumped when browsing exchange
    assertFalse(out.contains("Hello World"));
    out = (String) mbeanServer.invoke(name, "browseExchange", new Object[] { 1 }, new String[] { "java.lang.Integer" });
    assertNotNull(out);
    // message body is not dumped when browsing exchange
    assertFalse(out.contains("Bye World"));
    out = (String) mbeanServer.invoke(name, "browseMessageBody", new Object[] { 1 }, new String[] { "java.lang.Integer" });
    assertNotNull(out);
    assertEquals("Bye World", out);
}

@Test
public void testManagedCamelContext() throws Exception {
    MBeanServer mbeanServer = getMBeanServer();
    ObjectName on = getContextObjectName();
    ObjectName onRoute = getCamelObjectName(TYPE_ROUTE, "foo");
    assertTrue(mbeanServer.isRegistered(on), "Should be registered");
    String name = (String) mbeanServer.getAttribute(on, "CamelId");
    assertEquals(context.getManagementName(), name);
    assertTrue(mbeanServer.isRegistered(onRoute), "Should be registered");
    String state = (String) mbeanServer.getAttribute(onRoute, "State");
    assertEquals("Stopped", state);
    // start the route
    mbeanServer.invoke(onRoute, "start", null, null);
    state = (String) mbeanServer.getAttribute(onRoute, "State");
    assertEquals("Started", state);
    Object reply = mbeanServer.invoke(on, "requestBody", new Object[] { "direct:foo", "Hello World" }, new String[] { "java.lang.String", "java.lang.Object" });
    assertEquals("Bye World", reply);
    // stop Camel
    mbeanServer.invoke(on, "stop", null, null);
}

