    RestConsumerContextPathMatcher.ConsumerPath<?> path6 = RestConsumerContextPathMatcher.matchBestPath("POST", "/pet/findByStatus", consumerPaths);
    assertNull(path6);
    RestConsumerContextPathMatcher.ConsumerPath<?> path7 = RestConsumerContextPathMatcher.matchBestPath("GET", "/pet/123", consumerPaths);
    assertEquals("/pet/{petId}", path7.getConsumerPath());
    RestConsumerContextPathMatcher.ConsumerPath<?> path8 = RestConsumerContextPathMatcher.matchBestPath("POST", "/pet/222", consumerPaths);
    assertEquals("/pet/{petId}", path8.getConsumerPath());
