@Test
public void shouldPrintKubernetesManifest() {
    CamelJBangMain.run(createMain(), "kubernetes", "run", "classpath:route.yaml", "--disable-auto=true", "--image-group", "camel-test", "--output", "yaml");
    List<HasMetadata> resources = kubernetesClient.load(getKubernetesManifestAsStream(printer.getOutput())).items();
    Assertions.assertEquals(2, resources.size());
    Deployment deployment = resources.stream().filter(it -> Deployment.class.isAssignableFrom(it.getClass())).map(Deployment.class::cast).findFirst().orElseThrow(() -> new RuntimeCamelException("Missing deployment in Kubernetes manifest"));
    var matchLabels = deployment.getSpec().getSelector().getMatchLabels();
