    Assertions.assertTrue(camelPropLocation.contains("file:/etc/camel/conf.d/_secrets/test-secret/secret.properties"), "camel.component.properties.location property doesn't contain expected value file:/etc/camel/conf.d/_configmaps/multiple-config/ui.properties");
