@Test
public void testReload() throws Exception {
    CamelContext context = new DefaultCamelContext();
    context.start();
    String invalidRoute = "<route id=\"test\">\n" + "    <from uri=\"seda:xml\"/>\n" + "    <log message=\"Some valid message\"/>\n" + "\t<setHeader name=\"SomeHeader\">\n" + "\t\t<toosimple>XYZ</toosimple>\n" + "\t</setHeader>\n" + "</route>";
    String validRoute = "<route id=\"test\">\n" + "    <from uri=\"seda:xml\"/>\n" + "    <log message=\"Some valid message\"/>\n" + "\t<setHeader name=\"SomeHeader\">\n" + "\t\t<simple>XYZ</simple>\n" + "\t</setHeader>\n" + "</route>";
    Resource invalidResource = ResourceHelper.fromString("dummy.xml", invalidRoute);
    Resource validResource = ResourceHelper.fromString("dummy.xml", validRoute);
    RoutesLoader loader = PluginHelper.getRoutesLoader(context);
    try {
        loader.updateRoutes(invalidResource);
        Assertions.fail();
    } catch (Exception e) {
        // expected
        Assertions.assertInstanceOf(XmlPullParserLocationException.class, e);
    }
    loader.updateRoutes(validResource);
    Assertions.assertEquals(1, context.getRoutes().size());
    context.stop();
}

